<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>SmolVLM: Redefining Small and Efficient Multimodal Models</title>

    <!-- Fonts: Manrope (bold display + body) + JetBrains Mono (code/data accents) -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Manrope:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;700&family=Syne:wght@700;800&display=swap" rel="stylesheet">

    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES — ELECTRIC STUDIO VARIANT
           Technical dark theme: deep navy, electric teal, amber accent
           Not the generic purple-on-white — inspired by sci-fi terminal aesthetics
           =========================================== */
        :root {
            --bg-deep:      #080c14;
            --bg-panel:     #0e1626;
            --bg-card:      #141e30;
            --bg-card2:     #0f1923;
            --accent-teal:  #00c8aa;
            --accent-amber: #f5a623;
            --accent-blue:  #3d7aed;
            --accent-red:   #e05252;
            --accent-green: #3ecf8e;
            --text-primary: #eef1f7;
            --text-secondary: #7a8ba8;
            --text-dim:     #4a5568;
            --border:       rgba(255,255,255,0.07);
            --border-accent: rgba(0,200,170,0.3);

            --font-display: 'Syne', sans-serif;
            --font-body:    'Manrope', sans-serif;
            --font-mono:    'JetBrains Mono', monospace;

            --title-size:    clamp(1.6rem, 5vw, 4.2rem);
            --h2-size:       clamp(1.2rem, 3.2vw, 2.4rem);
            --h3-size:       clamp(0.95rem, 2.2vw, 1.5rem);
            --body-size:     clamp(0.72rem, 1.3vw, 1rem);
            --small-size:    clamp(0.6rem, 0.95vw, 0.82rem);
            --mono-size:     clamp(0.6rem, 1vw, 0.85rem);

            --slide-padding: clamp(1.2rem, 3.5vw, 3.5rem);
            --content-gap:   clamp(0.6rem, 1.8vw, 1.8rem);
            --element-gap:   clamp(0.3rem, 0.9vw, 0.9rem);

            --ease-expo:     cubic-bezier(0.16, 1, 0.3, 1);
            --dur-normal:    0.6s;
            --dur-fast:      0.3s;
        }

        /* ===========================================
           RESET
           =========================================== */
        *, *::before, *::after {
            margin: 0; padding: 0; box-sizing: border-box;
        }

        /* ===========================================
           VIEWPORT BASE — from viewport-base.css (mandatory inclusion)
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }
        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }
        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }
        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }
        .feature-list, .bullet-list {
            gap: clamp(0.4rem, 1vh, 1rem);
        }
        .feature-list li, .bullet-list li {
            font-size: var(--body-size);
            line-height: 1.4;
        }
        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        /* SHORT VIEWPORT BREAKPOINTS */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }
        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }
        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
        }
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           BASE THEME
           =========================================== */
        body {
            font-family: var(--font-body);
            background: var(--bg-deep);
            color: var(--text-primary);
        }

        /* ===========================================
           GLOBAL DECORATIVE BACKGROUND GRID
           Subtle structural lines across all slides
           =========================================== */
        .slide::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
            z-index: 0;
        }
        .slide > * { position: relative; z-index: 1; }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0; left: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-teal), var(--accent-blue));
            width: 0%;
            transition: width 0.3s var(--ease-expo);
            z-index: 9999;
            box-shadow: 0 0 8px var(--accent-teal);
        }

        /* ===========================================
           NAVIGATION DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.8rem, 2vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1vh, 0.75rem);
            z-index: 1000;
        }
        .nav-dot {
            width: clamp(5px, 0.6vw, 8px);
            height: clamp(5px, 0.6vw, 8px);
            border-radius: 50%;
            background: var(--text-dim);
            cursor: pointer;
            transition: all var(--dur-fast);
        }
        .nav-dot.active {
            background: var(--accent-teal);
            box-shadow: 0 0 8px var(--accent-teal);
            transform: scale(1.4);
        }

        /* ===========================================
           SLIDE NUMBER BADGE
           =========================================== */
        .slide-num {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-dim);
            letter-spacing: 0.08em;
        }

        /* ===========================================
           REVEAL ANIMATIONS
           Triggered by .visible class via IntersectionObserver
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(24px);
            transition: opacity var(--dur-normal) var(--ease-expo),
                        transform var(--dur-normal) var(--ease-expo);
        }
        .slide.visible .reveal { opacity: 1; transform: translateY(0); }
        .reveal-left {
            opacity: 0; transform: translateX(calc(-1 * clamp(20px, 3vw, 40px)));
            transition: opacity var(--dur-normal) var(--ease-expo), transform var(--dur-normal) var(--ease-expo);
        }
        .slide.visible .reveal-left { opacity: 1; transform: translateX(0); }
        .reveal-scale {
            opacity: 0; transform: scale(0.92);
            transition: opacity var(--dur-normal) var(--ease-expo), transform var(--dur-normal) var(--ease-expo);
        }
        .slide.visible .reveal-scale { opacity: 1; transform: scale(1); }

        /* Stagger delays */
        .d1 { transition-delay: 0.08s; }
        .d2 { transition-delay: 0.18s; }
        .d3 { transition-delay: 0.28s; }
        .d4 { transition-delay: 0.38s; }
        .d5 { transition-delay: 0.48s; }
        .d6 { transition-delay: 0.58s; }
        .d7 { transition-delay: 0.68s; }
        .d8 { transition-delay: 0.78s; }

        /* ===========================================
           SHARED COMPONENT: SLIDE HEADER BAND
           Thin top bar with slide label + number
           =========================================== */
        .slide-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: clamp(0.6rem, 1.5vh, 1.2rem) var(--slide-padding);
            border-bottom: 1px solid var(--border);
            flex-shrink: 0;
        }
        .slide-label {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent-teal);
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }
        .slide-count {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-dim);
        }

        /* ===========================================
           SHARED COMPONENT: ACCENT LINE
           Decorative teal rule under headings
           =========================================== */
        .accent-line {
            width: clamp(2rem, 5vw, 4rem);
            height: 3px;
            background: linear-gradient(90deg, var(--accent-teal), transparent);
            border-radius: 2px;
            margin: clamp(0.4rem, 1vh, 0.8rem) 0;
            flex-shrink: 0;
        }

        /* ===========================================
           SHARED COMPONENT: TAG / BADGE
           =========================================== */
        .tag {
            display: inline-block;
            font-family: var(--font-mono);
            font-size: var(--small-size);
            padding: 0.2em 0.7em;
            border-radius: 4px;
            border: 1px solid var(--border-accent);
            color: var(--accent-teal);
            background: rgba(0,200,170,0.08);
            letter-spacing: 0.05em;
        }
        .tag.amber { color: var(--accent-amber); border-color: rgba(245,166,35,0.3); background: rgba(245,166,35,0.08); }
        .tag.blue  { color: var(--accent-blue);  border-color: rgba(61,122,237,0.3); background: rgba(61,122,237,0.08); }
        .tag.green { color: var(--accent-green); border-color: rgba(62,207,142,0.3); background: rgba(62,207,142,0.08); }
        .tag.red   { color: var(--accent-red);   border-color: rgba(224,82,82,0.3);  background: rgba(224,82,82,0.08); }

        /* ===========================================
           SLIDE 1 — TITLE
           Full-bleed dark hero with glow accent
           =========================================== */
        #s1 {
            background:
                radial-gradient(ellipse at 10% 90%, rgba(0,200,170,0.12) 0%, transparent 55%),
                radial-gradient(ellipse at 90% 10%, rgba(61,122,237,0.1) 0%, transparent 55%),
                var(--bg-deep);
            justify-content: center;
        }
        .title-eyebrow {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent-teal);
            letter-spacing: 0.18em;
            text-transform: uppercase;
            margin-bottom: clamp(0.5rem, 1.5vh, 1rem);
        }
        .title-main {
            font-family: var(--font-display);
            font-size: var(--title-size);
            font-weight: 800;
            line-height: 1.08;
            color: var(--text-primary);
            max-width: 16ch;
            margin-bottom: clamp(0.6rem, 2vh, 1.2rem);
        }
        .title-main .accent-word {
            color: var(--accent-teal);
        }
        .title-subtitle {
            font-size: var(--body-size);
            color: var(--text-secondary);
            max-width: 55ch;
            line-height: 1.6;
            margin-bottom: clamp(0.8rem, 2.5vh, 1.8rem);
        }
        .title-meta {
            display: flex;
            gap: clamp(0.5rem, 1.5vw, 1rem);
            flex-wrap: wrap;
            align-items: center;
        }
        .title-meta .tag { flex-shrink: 0; }

        /* Corner accent — decorative large circle */
        .corner-glow {
            position: absolute;
            width: clamp(200px, 40vw, 600px);
            height: clamp(200px, 40vw, 600px);
            border-radius: 50%;
            background: radial-gradient(circle, rgba(0,200,170,0.06) 0%, transparent 70%);
            border: 1px solid rgba(0,200,170,0.08);
            right: calc(-1 * clamp(80px, 12vw, 160px));
            top: calc(-1 * clamp(80px, 12vw, 160px));
            pointer-events: none;
        }
        .corner-glow2 {
            position: absolute;
            width: clamp(120px, 22vw, 320px);
            height: clamp(120px, 22vw, 320px);
            border-radius: 50%;
            background: radial-gradient(circle, rgba(61,122,237,0.07) 0%, transparent 70%);
            border: 1px solid rgba(61,122,237,0.06);
            left: calc(-1 * clamp(40px, 6vw, 80px));
            bottom: calc(-1 * clamp(40px, 6vw, 80px));
            pointer-events: none;
        }

        /* ===========================================
           SLIDE 2 — PROBLEM / MOTIVATION
           Two-panel: stat cards left, text right
           =========================================== */
        #s2 { background: var(--bg-panel); }
        .problem-layout {
            display: grid;
            grid-template-columns: 1fr 1.4fr;
            gap: clamp(1rem, 3vw, 2.5rem);
            height: 100%;
            align-items: center;
        }
        .stat-stack {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1rem);
        }
        .stat-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-left: 3px solid var(--accent-teal);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.5vh, 1.1rem) clamp(0.8rem, 2vw, 1.4rem);
        }
        .stat-card.warn { border-left-color: var(--accent-red); }
        .stat-card.amber { border-left-color: var(--accent-amber); }
        .stat-num {
            font-family: var(--font-display);
            font-size: clamp(1.4rem, 3.5vw, 2.8rem);
            font-weight: 800;
            color: var(--accent-teal);
            line-height: 1;
        }
        .stat-card.warn .stat-num { color: var(--accent-red); }
        .stat-card.amber .stat-num { color: var(--accent-amber); }
        .stat-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.2em;
        }
        .problem-text h2 {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 800;
            color: var(--text-primary);
            line-height: 1.2;
            margin-bottom: clamp(0.5rem, 1.5vh, 1rem);
        }
        .bullet-items {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1vh, 0.8rem);
        }
        .bullet-items li {
            font-size: var(--body-size);
            color: var(--text-secondary);
            padding-left: clamp(1rem, 2vw, 1.4rem);
            position: relative;
            line-height: 1.5;
        }
        .bullet-items li::before {
            content: '›';
            position: absolute;
            left: 0;
            color: var(--accent-teal);
            font-weight: 700;
        }
        .bullet-items li strong { color: var(--text-primary); }

        @media (max-width: 768px) {
            .problem-layout { grid-template-columns: 1fr; }
            .stat-stack { flex-direction: row; flex-wrap: wrap; }
        }

        /* ===========================================
           SLIDE 3 — ARCHITECTURE
           Horizontal pipeline flow diagram
           =========================================== */
        #s3 {
            background:
                radial-gradient(ellipse at 80% 50%, rgba(61,122,237,0.08) 0%, transparent 60%),
                var(--bg-deep);
        }
        .arch-pipeline {
            display: flex;
            align-items: center;
            gap: clamp(0.3rem, 1vw, 0.8rem);
            overflow-x: auto;
            padding-bottom: clamp(0.2rem, 0.5vh, 0.4rem);
            flex-shrink: 0;
            max-width: 100%;
        }
        .pipe-step {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: clamp(0.3rem, 0.8vh, 0.6rem);
            flex-shrink: 0;
        }
        .pipe-box {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.4rem, 1vh, 0.8rem) clamp(0.5rem, 1.2vw, 1rem);
            text-align: center;
            min-width: clamp(70px, 9vw, 120px);
        }
        .pipe-box.highlight {
            border-color: var(--accent-teal);
            background: rgba(0,200,170,0.06);
        }
        .pipe-icon {
            font-size: clamp(1rem, 2.5vw, 1.8rem);
            margin-bottom: 0.2em;
        }
        .pipe-name {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-primary);
            white-space: nowrap;
        }
        .pipe-detail {
            font-size: clamp(0.5rem, 0.8vw, 0.68rem);
            color: var(--text-secondary);
            white-space: nowrap;
        }
        .pipe-arrow {
            font-size: clamp(0.8rem, 1.8vw, 1.4rem);
            color: var(--accent-teal);
            flex-shrink: 0;
            align-self: center;
            padding-bottom: clamp(0.8rem, 2vh, 1.4rem);
        }
        .pipe-label {
            font-size: clamp(0.5rem, 0.7vw, 0.62rem);
            color: var(--text-dim);
            text-align: center;
            max-width: clamp(70px, 9vw, 120px);
        }
        .arch-findings {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: clamp(0.5rem, 1.2vw, 1rem);
            margin-top: clamp(0.5rem, 1.5vh, 1rem);
        }
        .finding-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.2vh, 1rem) clamp(0.6rem, 1.2vw, 1rem);
        }
        .finding-num {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent-teal);
            margin-bottom: 0.3em;
        }
        .finding-text {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.45;
        }
        .finding-text strong { color: var(--text-primary); }

        /* ===========================================
           SLIDE 4 — COMPUTE ALLOCATION
           Bar chart: encoder size vs. performance
           =========================================== */
        #s4 {
            background:
                radial-gradient(ellipse at 20% 80%, rgba(245,166,35,0.07) 0%, transparent 55%),
                var(--bg-panel);
        }
        .compute-layout {
            display: grid;
            grid-template-columns: 1.2fr 1fr;
            gap: clamp(1rem, 3vw, 2.5rem);
            align-items: center;
            height: 100%;
        }
        .chart-area {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1vh, 0.8rem);
        }
        .chart-title {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-dim);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            margin-bottom: clamp(0.2rem, 0.5vh, 0.4rem);
        }
        .bar-group {
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.8vh, 0.6rem);
        }
        .bar-row {
            display: grid;
            grid-template-columns: clamp(5rem, 10vw, 10rem) 1fr clamp(2rem, 3.5vw, 3.5rem);
            gap: clamp(0.4rem, 0.8vw, 0.8rem);
            align-items: center;
        }
        .bar-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: right;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        .bar-track {
            height: clamp(12px, 2.5vh, 22px);
            background: rgba(255,255,255,0.04);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }
        .bar-fill {
            height: 100%;
            border-radius: 4px;
            transition: width 1s var(--ease-expo);
        }
        .bar-fill.small { background: linear-gradient(90deg, var(--accent-teal), rgba(0,200,170,0.5)); }
        .bar-fill.large { background: linear-gradient(90deg, var(--accent-amber), rgba(245,166,35,0.5)); }
        .bar-fill.large2 { background: linear-gradient(90deg, var(--accent-blue), rgba(61,122,237,0.5)); }
        .bar-val {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-primary);
            text-align: left;
        }
        .separator-line {
            height: 1px;
            background: var(--border);
            margin: clamp(0.3rem, 0.8vh, 0.6rem) 0;
        }
        .compute-insight {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.2vh, 1rem);
        }
        .insight-block {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.2vh, 1rem) clamp(0.6rem, 1.2vw, 1rem);
        }
        .insight-block.highlight-teal {
            border-color: var(--border-accent);
            background: rgba(0,200,170,0.05);
        }
        .insight-block.highlight-amber {
            border-color: rgba(245,166,35,0.3);
            background: rgba(245,166,35,0.05);
        }
        .insight-head {
            font-size: var(--small-size);
            font-weight: 700;
            color: var(--accent-teal);
            margin-bottom: 0.3em;
        }
        .insight-block.highlight-amber .insight-head { color: var(--accent-amber); }
        .insight-body {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }
        .insight-body strong { color: var(--text-primary); }

        /* ===========================================
           SLIDE 5 — TOKEN COMPRESSION
           Visual pixel-shuffle diagram
           =========================================== */
        #s5 {
            background:
                radial-gradient(ellipse at 70% 30%, rgba(61,122,237,0.09) 0%, transparent 55%),
                var(--bg-deep);
        }
        .token-layout {
            display: grid;
            grid-template-columns: 1.1fr 1fr;
            gap: clamp(1rem, 2.5vw, 2rem);
            align-items: center;
            height: 100%;
        }
        /* Pixel shuffle visual */
        .shuffle-visual {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: clamp(0.3rem, 1vh, 0.7rem);
        }
        .shuffle-step-label {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-dim);
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }
        /* Input grid: 4×4 spatial cells */
        .grid-vis {
            display: grid;
            border: 1px solid var(--border-accent);
            border-radius: 6px;
            overflow: hidden;
        }
        .grid-vis.input-grid {
            grid-template-columns: repeat(8, 1fr);
            grid-template-rows: repeat(8, 1fr);
            width: clamp(100px, 18vw, 180px);
            height: clamp(100px, 18vw, 180px);
        }
        .grid-vis.output-grid {
            grid-template-columns: repeat(2, 1fr);
            grid-template-rows: repeat(2, 1fr);
            width: clamp(50px, 9vw, 92px);
            height: clamp(50px, 9vw, 92px);
        }
        .grid-cell {
            border: 1px solid rgba(0,200,170,0.08);
        }
        .grid-cell.c0 { background: rgba(0,200,170,0.25); }
        .grid-cell.c1 { background: rgba(61,122,237,0.25); }
        .grid-cell.c2 { background: rgba(245,166,35,0.25); }
        .grid-cell.c3 { background: rgba(224,82,82,0.25); }
        .grid-cell.c0.deep { background: rgba(0,200,170,0.5); }
        .grid-cell.c1.deep { background: rgba(61,122,237,0.5); }
        .grid-cell.c2.deep { background: rgba(245,166,35,0.5); }
        .grid-cell.c3.deep { background: rgba(224,82,82,0.5); }
        .shuffle-arrow {
            font-size: clamp(1rem, 2.5vw, 1.8rem);
            color: var(--accent-teal);
        }
        .shuffle-metrics {
            display: flex;
            gap: clamp(0.5rem, 1.5vw, 1.2rem);
            margin-top: clamp(0.2rem, 0.5vh, 0.4rem);
        }
        .metric-pill {
            display: flex;
            flex-direction: column;
            align-items: center;
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.3rem, 0.8vh, 0.6rem) clamp(0.5rem, 1.2vw, 1rem);
        }
        .metric-val {
            font-family: var(--font-display);
            font-size: clamp(1rem, 2.5vw, 2rem);
            font-weight: 800;
            color: var(--accent-teal);
            line-height: 1;
        }
        .metric-label {
            font-family: var(--font-mono);
            font-size: clamp(0.45rem, 0.7vw, 0.6rem);
            color: var(--text-dim);
            text-align: center;
            margin-top: 0.2em;
            text-transform: uppercase;
            letter-spacing: 0.06em;
        }
        .token-info {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.2vh, 1rem);
        }
        .r-compare {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1vh, 0.8rem);
        }
        .r-row {
            display: grid;
            grid-template-columns: clamp(2.5rem, 4vw, 3.5rem) 1fr;
            gap: clamp(0.4rem, 0.8vw, 0.8rem);
            align-items: center;
        }
        .r-badge {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            font-weight: 700;
            background: var(--bg-card2);
            border: 1px solid var(--border);
            border-radius: 5px;
            padding: 0.2em 0.4em;
            text-align: center;
            color: var(--accent-teal);
        }
        .r-badge.dim { color: var(--text-dim); }
        .r-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.4;
        }
        .r-desc strong { color: var(--text-primary); }

        /* ===========================================
           SLIDE 6 — CONTEXT LENGTH SCALING
           =========================================== */
        #s6 {
            background:
                radial-gradient(ellipse at 15% 20%, rgba(62,207,142,0.07) 0%, transparent 55%),
                var(--bg-panel);
        }
        .context-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1rem, 2.5vw, 2.5rem);
            align-items: center;
            height: 100%;
        }
        .context-diagram {
            display: flex;
            flex-direction: column;
            gap: clamp(0.4rem, 1.2vh, 1rem);
        }
        .context-row {
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1.2vw, 1rem);
        }
        .ctx-label {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-secondary);
            white-space: nowrap;
            width: clamp(4rem, 7vw, 7rem);
            text-align: right;
        }
        .ctx-bar-wrap {
            flex: 1;
            height: clamp(16px, 3vh, 28px);
            background: rgba(255,255,255,0.04);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }
        .ctx-bar {
            height: 100%;
            border-radius: 4px;
            display: flex;
            align-items: center;
            padding-left: 0.5em;
            font-family: var(--font-mono);
            font-size: clamp(0.5rem, 0.8vw, 0.68rem);
            color: rgba(0,0,0,0.8);
            font-weight: 700;
            transition: width 1.2s var(--ease-expo) 0.3s;
        }
        .ctx-bar.before { background: linear-gradient(90deg, #4a5568, #6b7280); width: 12.5%; }
        .ctx-bar.after8  { background: linear-gradient(90deg, var(--accent-teal), rgba(0,200,170,0.7)); width: 50%; }
        .ctx-bar.after16 { background: linear-gradient(90deg, var(--accent-blue), rgba(61,122,237,0.7)); width: 100%; }
        .ctx-note {
            font-family: var(--font-mono);
            font-size: clamp(0.45rem, 0.65vw, 0.58rem);
            color: var(--text-dim);
            white-space: nowrap;
        }
        .context-facts {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.2vh, 1rem);
        }
        .fact-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.2vh, 1rem) clamp(0.6rem, 1.2vw, 1rem);
        }
        .fact-head {
            font-size: var(--small-size);
            font-weight: 700;
            color: var(--accent-green);
            margin-bottom: 0.25em;
        }
        .fact-body {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }
        .fact-body strong { color: var(--text-primary); }
        .rope-vis {
            display: flex;
            align-items: center;
            gap: clamp(0.4rem, 1vw, 0.8rem);
            padding: clamp(0.4rem, 1vh, 0.8rem) clamp(0.6rem, 1.2vw, 1rem);
            background: var(--bg-card2);
            border: 1px solid var(--border);
            border-radius: 8px;
            margin-top: clamp(0.3rem, 0.8vh, 0.6rem);
        }
        .rope-label {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-dim);
        }
        .rope-arrow-line {
            flex: 1;
            height: 2px;
            background: linear-gradient(90deg, #4a5568, var(--accent-green));
            position: relative;
        }
        .rope-arrow-line::after {
            content: '▶';
            position: absolute;
            right: 0;
            top: 50%;
            transform: translateY(-50%);
            color: var(--accent-green);
            font-size: 0.6em;
        }
        .rope-new {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent-green);
            font-weight: 700;
        }

        /* ===========================================
           SLIDE 7 — BENCHMARK PERFORMANCE
           Full data table
           =========================================== */
        #s7 {
            background:
                radial-gradient(ellipse at 90% 90%, rgba(0,200,170,0.06) 0%, transparent 55%),
                var(--bg-deep);
        }
        .bench-table-wrap {
            overflow: hidden;
            flex-shrink: 1;
            min-height: 0;
        }
        .bench-table {
            width: 100%;
            border-collapse: collapse;
            font-size: clamp(0.55rem, 0.85vw, 0.78rem);
        }
        .bench-table th {
            font-family: var(--font-mono);
            font-size: clamp(0.48rem, 0.75vw, 0.68rem);
            color: var(--text-dim);
            text-transform: uppercase;
            letter-spacing: 0.08em;
            padding: clamp(0.25rem, 0.6vh, 0.5rem) clamp(0.4rem, 0.8vw, 0.8rem);
            border-bottom: 1px solid var(--border);
            text-align: right;
            white-space: nowrap;
        }
        .bench-table th:first-child,
        .bench-table th:nth-child(2) { text-align: left; }
        .bench-table td {
            padding: clamp(0.2rem, 0.5vh, 0.45rem) clamp(0.4rem, 0.8vw, 0.8rem);
            border-bottom: 1px solid rgba(255,255,255,0.03);
            color: var(--text-secondary);
            text-align: right;
            white-space: nowrap;
        }
        .bench-table td:first-child { text-align: left; }
        .bench-table td:nth-child(2) {
            color: var(--text-primary);
            font-weight: 500;
            text-align: left;
        }
        .bench-table tr:hover td { background: rgba(255,255,255,0.02); }
        .bench-table .section-header td {
            background: rgba(255,255,255,0.03);
            color: var(--text-dim);
            font-family: var(--font-mono);
            font-size: clamp(0.45rem, 0.68vw, 0.6rem);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            text-align: left;
            padding: clamp(0.15rem, 0.35vh, 0.3rem) clamp(0.4rem, 0.8vw, 0.8rem);
        }
        .bench-table .avg-row td {
            background: rgba(0,200,170,0.05);
            border-top: 1px solid var(--border-accent);
            font-weight: 700;
        }
        .bench-table .avg-row td:nth-child(2) { color: var(--accent-teal); }
        .val-best { color: var(--accent-green) !important; font-weight: 700; }
        .val-256m { color: clamp(0.55rem, 0.85vw, 0.78rem); color: var(--text-secondary); }
        .val-ram {
            font-family: var(--font-mono);
            font-size: clamp(0.48rem, 0.72vw, 0.64rem);
        }
        .ram-row td { background: rgba(61,122,237,0.04); border-top: 1px solid rgba(61,122,237,0.15); }
        .ram-row td:nth-child(2) { color: var(--accent-blue); }
        .bench-summary {
            display: flex;
            gap: clamp(0.5rem, 1.2vw, 1rem);
            flex-wrap: wrap;
            margin-top: clamp(0.4rem, 1vh, 0.8rem);
            flex-shrink: 0;
        }
        .bench-sum-card {
            flex: 1;
            min-width: clamp(80px, 14vw, 130px);
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.4rem, 0.9vh, 0.8rem) clamp(0.5rem, 1vw, 0.9rem);
            text-align: center;
        }
        .bsc-val {
            font-family: var(--font-display);
            font-size: clamp(1rem, 2.2vw, 1.8rem);
            font-weight: 800;
            line-height: 1;
        }
        .bsc-val.t  { color: var(--accent-teal); }
        .bsc-val.b  { color: var(--accent-blue); }
        .bsc-val.g  { color: var(--accent-green); }
        .bsc-val.r  { color: var(--accent-red); }
        .bsc-label {
            font-size: clamp(0.45rem, 0.7vw, 0.62rem);
            color: var(--text-dim);
            margin-top: 0.2em;
            line-height: 1.3;
        }

        /* ===========================================
           SLIDE 8 — ON-DEVICE DEPLOYMENT
           =========================================== */
        #s8 {
            background:
                radial-gradient(ellipse at 30% 70%, rgba(62,207,142,0.08) 0%, transparent 55%),
                var(--bg-panel);
        }
        .device-layout {
            display: grid;
            grid-template-columns: 1.2fr 1fr;
            gap: clamp(1rem, 2.5vw, 2rem);
            align-items: center;
            height: 100%;
